\label{tab:main}
\small
\begin{tabular}{@{}lcccccccc@{}}
\toprule
\multirow{2}{*}{Model} & \multirow{2}{*}{$C_0$} & \multicolumn{2}{c}{FOLIO} & \multicolumn{2}{c}{ProofWriter} & \multicolumn{2}{c}{Combined} \\
\cmidrule(lr){3-4} \cmidrule(lr){5-6} \cmidrule(lr){7-8}
