\multicolumn{8}{l}{\textit{Instruction Models ($C_0 > 20\%$)}} \\
\midrule
Qwen2.5-7B & 0.55 & 63.3 & 70.0 & 60.7 & 61.9 & 61.7 & 65.0 \\
Qwen2.5-14B$^\dagger$ & 0.42 & 74.5 & 78.4 & 68.9 & 69.5 & 70.3 & 71.8 \\
